// Everything the writer and the reviewer get, gathered once per execution (also on a retry). Generation only starts
// when the base CV is ready: analysed, and the stored file is the one that was analysed.
const run = $('Claim one run').first().json;
const job = $('Load inputs').first().json;
const res = $json; // the worker's read of the stored documents
const fail = (error, final) => ({ json: { ready: false, run_id: run.id, claimed_at: run.claimed_at, error, final } });

if (!job.job_id) return fail('The job was not found.', true);
if (job.extraction_status !== 'done') return fail("The job's details have not been read yet.", true);
if (!job.cv_id) return fail("Your base CV isn't ready.", true);
const httpOk = typeof res.statusCode === 'number' && res.statusCode >= 200 && res.statusCode < 300;
const documents = httpOk && res.body && Array.isArray(res.body.documents) ? res.body.documents : null;
// The worker did not answer: a failed attempt, tried again later.
if (!documents) return fail('Your base CV file could not be read; it will be tried again.', false);
const stored = documents.find((d) => d.kind === 'cv');
// Replaced since its analysis, or unreadable: the analysed facts would not match the file sent.
if (!stored || stored.contentHash !== job.cv_hash || (!stored.pdfBase64 && !stored.text)) {
  return fail("Your base CV isn't ready.", true);
}

const cv_block = stored.pdfBase64
  ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: stored.pdfBase64 } }
  : { type: 'text', text: '<document>\n' + stored.text + '\n</document>' };
// A regenerate (the run carries Prayush's instruction and the version it starts from; a retry keeps both).
// Its documents must be complete, as the worker would accept them; if not, the run stops before any call.
const REGEN_UNUSABLE = 'The version to regenerate from could not be used.';
const isObj = (x) => typeof x === 'object' && x !== null && !Array.isArray(x);
const isStr = (x, empty = false) => typeof x === 'string' && (empty || x.trim() !== '');
const strOrNull = (x) => x === null || isStr(x);
const all = (x, f) => Array.isArray(x) && x.every(f);
const strings = (x) => all(x, (s) => isStr(s));
const validCv = (c) =>
  isObj(c) && isStr(c.name) && isStr(c.headline, true) && isStr(c.summary, true) && strOrNull(c.workRights) &&
  isObj(c.contact) && strOrNull(c.contact.location) && strOrNull(c.contact.email) && strOrNull(c.contact.phone) &&
  all(c.contact.links, (l) => isObj(l) && isStr(l.label) && isStr(l.url)) &&
  all(c.skills, (g) => isObj(g) && isStr(g.group) && strings(g.items)) &&
  all(c.experience, (e) => isObj(e) && isStr(e.title) && isStr(e.employer) && strOrNull(e.location) && isStr(e.dates, true) && strings(e.bullets)) &&
  all(c.education, (e) => isObj(e) && ['qualification', 'institution', 'dates', 'statusText'].every((k) => isStr(e[k], true))) &&
  all(c.projects, (p) => isObj(p) && isStr(p.name) && strings(p.bullets));
const validLetter = (l) =>
  isObj(l) && isStr(l.date) && isStr(l.addressee, true) && isStr(l.salutation) && strings(l.paragraphs) && isStr(l.signOff) && isStr(l.name);
// Manual edits are kept by text: { path, text } (text: what Prayush wrote there, null for a field he
// emptied). An edit is where its text is: at its path, or moved within the same list (a reordered or
// shifted bullet). Rows saved before this held paths only; they are read as the text at that path.
const meParts = (p) => String(p).match(/[^.[\]]+|\[\d+\]/g) || [];
const meAt = (docs, p) => {
  const parts = meParts(p);
  if (parts.length === 0) return { found: false };
  let x = docs;
  for (const part of parts) {
    if (part[0] === '[') {
      const i = Number(part.slice(1, -1));
      if (!Array.isArray(x) || i >= x.length) return { found: false };
      x = x[i];
    } else {
      if (typeof x !== 'object' || x === null || Array.isArray(x) || !Object.prototype.hasOwnProperty.call(x, part)) return { found: false };
      x = x[part];
    }
  }
  return { found: true, value: x };
};
// Every text field at or under a path, as { path, text }.
const meLeaves = (v, p, out = []) => {
  if (typeof v === 'string' || v === null) out.push({ path: p, text: v });
  else if (Array.isArray(v)) v.forEach((x, i) => meLeaves(x, `${p}[${i}]`, out));
  else if (typeof v === 'object' && v !== undefined) for (const k of Object.keys(v)) meLeaves(v[k], `${p}.${k}`, out);
  return out;
};
// The list a list item is in ("cv.experience[0].bullets" for "cv.experience[0].bullets[2]"), else null.
const meList = (p) => (/\[\d+\]$/.test(p) ? p.replace(/\[\d+\]$/, '') : null);
const meRead = (raw, docs) => {
  const out = [];
  const seen = new Set();
  for (const e of Array.isArray(raw) ? raw : []) {
    let items = [];
    if (typeof e === 'string') {
      const at = meAt(docs, e);
      if (at.found) items = meLeaves(at.value, e);
    } else if (e && typeof e === 'object' && typeof e.path === 'string' && (typeof e.text === 'string' || e.text === null)) {
      items = [{ path: e.path, text: e.text }];
    }
    for (const it of items) if (!seen.has(it.path)) { seen.add(it.path); out.push(it); }
  }
  return out;
};
// Where each edit is in these documents: { path, text } (path updated if it moved), or null when its text is gone.
const meLocate = (edits, docs) => {
  const here = edits.map((e) => { const at = meAt(docs, e.path); return at.found && at.value === e.text; });
  const used = new Set(edits.filter((e, i) => here[i]).map((e) => e.path));
  return edits.map((e, i) => {
    if (here[i]) return { path: e.path, text: e.text };
    const list = typeof e.text === 'string' ? meList(e.path) : null;
    const items = list ? meAt(docs, list) : { found: false };
    if (!items.found || !Array.isArray(items.value)) return null;
    const j = items.value.findIndex((v, k) => v === e.text && !used.has(`${list}[${k}]`));
    if (j < 0) return null;
    used.add(`${list}[${j}]`);
    return { path: `${list}[${j}]`, text: e.text };
  });
};
let regenerate = null;
if (run.instruction != null || run.from_version_id != null) {
  const fv = job.from_version;
  if (!isStr(run.instruction) || !run.from_version_id || !isObj(fv) || fv.id !== run.from_version_id || !validCv(fv.cv) || !validLetter(fv.cover_letter)) {
    return fail(REGEN_UNUSABLE, true);
  }
  // Prayush's manual edits, locked by text: the writer copies each one exactly. Only those whose text is in
  // the version (an old path-only row: the text at that path now).
  const fvDocs = { cv: fv.cv, coverLetter: fv.cover_letter };
  const edits = meLocate(meRead(isObj(fv.reasons) ? fv.reasons.manualEdits : [], fvDocs), fvDocs).filter(Boolean);
  regenerate = {
    instruction: run.instruction,
    from_version_id: fv.id,
    from_version_no: fv.version_no,
    current_version: { cv: fv.cv, coverLetter: fv.cover_letter },
    manual_edits: edits,
  };
}

const letter = job.cl_structured;
const inputs = {
  job_id: job.job_id,
  job_ad: job.raw_text ?? '',
  job_facts: { title: job.title, employer: job.employer, advertiser: job.advertiser, shortDescription: job.short_description },
  base_cv_facts: job.cv_structured,
  // The base cover letter goes only as its analysis, never as its text.
  base_cover_letter: letter
    ? { previousTarget: letter.previousTarget ?? null, reusableParagraphs: letter.reusableParagraphs ?? [], toneNotes: letter.toneNotes ?? '' }
    : null,
  company_notes: job.company_notes ?? '',
  other_jobs: Array.isArray(job.other_jobs) ? job.other_jobs : [],
  cv_block,
  cv_id: job.cv_id,
  cv_hash: job.cv_hash,
  cl_id: letter ? job.cl_id : null,
  cl_hash: letter ? job.cl_hash : null,
  regenerate,
};
// A retry continues where the last attempt stopped. The rounds it recorded must have been written from
// these same base documents; if the CV or cover letter changed since, the run stops (no mixing).
const recorded = Array.isArray(run.rounds) ? run.rounds : [];
if (recorded.some((r) => r.base_cv_hash !== inputs.cv_hash || (r.base_cover_letter_hash ?? null) !== (inputs.cl_hash ?? null))) {
  return fail('Your base documents changed while this was being written. Choose Generate again.', true);
}
// Every round already recorded, or one already passed (its save failed), or one whose only problems are inside
// Prayush's locked edits (no round can fix those): straight to the save, no Claude call.
const max = $('Look up model prices').first().json.max_rounds;
const another = recorded.length < max && !recorded.some((r) => r.passed === true || r.lockedOnly === true);
return { json: { ready: true, run_id: run.id, claimed_at: run.claimed_at, round: recorded.length + 1, another, rounds: recorded, inputs } };

// The writer's request for this round. On a revision the previous round comes from the run's row
// in the database (returned by the heartbeat), not from an earlier pass through the loop.
const beat = $json; // id, claimed_at (the renewed claim token), round, rounds
const { inputs } = $('Prepare inputs').first().json;
const prompts = $('Writer and reviewer prompts').first().json;
const price = $('Look up model prices').first().json.writer;
const rounds = Array.isArray(beat.rounds) ? beat.rounds : [];
if (rounds.length !== beat.round - 1) {
  throw new Error(`Round ${beat.round} found ${rounds.length} recorded rounds in the run; stopping before calling Claude.`);
}
const prev = rounds[rounds.length - 1] ?? null;

// The writer writes "" for "none" in these fields ("Read the writer's answer" stores null). It is shown
// its previous documents in its own format, so it never takes null for a change it has to make or explain.
const inWriterFormat = (documents) => {
  const d = JSON.parse(JSON.stringify(documents ?? null));
  const blank = (o, key) => {
    if (o && typeof o === 'object' && o[key] === null) o[key] = '';
  };
  if (d && d.cv && typeof d.cv === 'object') {
    blank(d.cv.contact, 'location');
    blank(d.cv.contact, 'email');
    blank(d.cv.contact, 'phone');
    blank(d.cv, 'workRights');
    if (Array.isArray(d.cv.experience)) for (const e of d.cv.experience) blank(e, 'location');
  }
  return d;
};

const tagged = (name, value) =>
  `<${name}>\n${typeof value === 'string' ? value : JSON.stringify(value, null, 2)}\n</${name}>`;
const parts = [
  tagged('job_ad', inputs.job_ad),
  tagged('job_facts', inputs.job_facts),
  tagged('base_cv_facts', inputs.base_cv_facts),
  tagged('base_cover_letter', inputs.base_cover_letter ?? 'none'),
  tagged('company_notes', inputs.company_notes),
];
// A regenerate: round 1 starts from the chosen version (in the writer's own "" format); every round
// carries Prayush's locked manual edits ({ path, text }, "" for a field he emptied) and his instruction.
// The instruction goes as a JSON string with "<" escaped, so its text can never close or open a tag.
// Rounds 2+ revise <previous_round> as usual.
const regen = inputs.regenerate ?? null;
const locked = regen && Array.isArray(regen.manual_edits) ? regen.manual_edits : [];
const jsonText = (s) => JSON.stringify(String(s)).replace(/</g, '\\u003c');
if (regen && !prev) parts.push(tagged('current_version', inWriterFormat(regen.current_version)));
if (regen) {
  parts.push(tagged('manual_edits', locked.map((e) => ({ path: e.path, text: e.text === null ? '' : e.text }))));
  parts.push(tagged('instruction', jsonText(regen.instruction)));
}
if (prev) {
  // A round whose documents the worker rejected was not reviewed: only its invalid_document check goes back.
  const review = prev.review ?? { items: [], objections: [], factRulings: [], spellingRulings: [] };
  const invented = review.factRulings.filter((r) => r.ruling === 'invented');
  const misspelt = review.spellingRulings.filter((r) => r.ruling === 'misspelt');
  // A review check still open: the reviewer ruled against it (an unmatched skill ruled invented, a word
  // ruled misspelt) or did not rule on it at all. Only an honest_rephrase / ok ruling that names it settles it.
  const settled = (c) => {
    const detail = String(c.detail ?? '').toLowerCase();
    const named = (s) => detail === String(s).toLowerCase() || detail.includes(`"${String(s).toLowerCase()}"`);
    if (c.code === 'unmatched_skill') return review.factRulings.some((r) => r.ruling === 'honest_rephrase' && named(r.text));
    if (c.code === 'possible_misspelling') return review.spellingRulings.some((r) => r.ruling === 'ok' && named(r.word));
    return false;
  };
  // Problems inside Prayush's locked edits are his to keep: never sent back (the checks mark them locked;
  // a ruling is about one when its text is inside a locked edit or it names a locked check).
  const lockedTexts = locked.map((e) => String(e.text ?? '').toLowerCase()).filter((t) => t !== '');
  const aboutLocked = (s) => {
    const t = String(s ?? '').toLowerCase();
    if (t !== '' && lockedTexts.some((x) => x.includes(t))) return true;
