    ok,
    error,
    final: false,
    review,
    passed,
    // What "Record the round" appends to the run's rounds.
    round_record: ok ? { round: state.round, writer, checks, cvPages, letterPages, review, passed, unruled, ...(lockedOnly ? { lockedOnly: true } : {}) } : null,
    purpose: 'review_documents',
    model,
    has_usage,
    input_tokens: has_usage ? usage.input_tokens : null,
    output_tokens: has_usage ? usage.output_tokens : null,
