return { json: $("Read the reviewer's answer").first().json };

// After a recorded round: save when it passed, when its only problems are inside Prayush's locked edits
// (lockedOnly: no round can fix those), or it was the last round; otherwise go round again.
// Everything comes from the run's row in the database.
const row = $json; // id, claimed_at (renewed), round, rounds
const max = $('Look up model prices').first().json.max_rounds;
