collect($('Claim one run'));
collect($('Heartbeat: writing'));
collect($('Heartbeat: checking'));
collect($('Heartbeat: reviewing'));
collect($('Record the round'));
const first = $input.first()?.json ?? {};
const raw = typeof first.error === 'string' ? first.error : first.error?.message ?? first.message ?? '';
const detail = String(raw).slice(0, 200);
return [
  {
    json: {
      run_id: run.id ?? null,
      tokens: [...new Set(tokens)],
      error: `Generation hit an unexpected error${detail ? ` (${detail})` : ''}.`,
    },
  },
];
